#include "ui_core.hpp"
#include <cassert>
int main() { spring::ui::Router router; assert(router.route() == spring::ui::Route::clock); assert(router.dispatch(spring::ui::Event::right)); assert(router.route() == spring::ui::Route::network); assert(router.dispatch(spring::ui::Event::left)); assert(router.route() == spring::ui::Route::clock); assert(router.dispatch(spring::ui::Event::right)); assert(router.dispatch(spring::ui::Event::right)); assert(router.dispatch(spring::ui::Event::right)); assert(router.dispatch(spring::ui::Event::right)); assert(router.route() == spring::ui::Route::settings); assert(router.dispatch(spring::ui::Event::down)); assert(router.setting_index() == 1); assert(router.dispatch(spring::ui::Event::up)); assert(router.setting_index() == 0); assert(router.dispatch(spring::ui::Event::confirm)); assert(router.dispatch(spring::ui::Event::left)); assert(router.route() == spring::ui::Route::call); assert(router.dispatch(spring::ui::Event::sleep)); assert(router.route() == spring::ui::Route::sleep); assert(!router.dispatch(spring::ui::Event::right)); assert(router.dispatch(spring::ui::Event::home)); assert(router.route() == spring::ui::Route::clock); spring::ui::Frame frame; frame.pixel(400, 300); assert(!frame.is_black(399, 299)); spring::ui::Frame next; next.pixel(9, 10); const auto dirty = next.difference(frame); assert(dirty.x == 8 && dirty.y == 10 && dirty.width == 8 && dirty.height == 1); return 0; }
